        nukeEnabled: Boolean(chkAdaptiveNuke?.checked),
        nukeAttack: selectAdaptiveNukeAttack?.value || configuredNukeAttack || 'auto',
        nukeAllowAbilities: Boolean(chkAdaptiveNukeAbilities?.checked),
