async function saveMonsterRow(areaKey, monsterKey, name, controls) {
  const entry = {
    name,
    targetDamage: Math.max(0, Math.trunc(Number(controls.targetDamage.value) || 0)),
    killCount: Math.max(0, Math.trunc(Number(controls.killCount.value) || 0)),
    dungeonKillCount: Math.max(0, Math.trunc(Number(controls.dungeonKillCount?.value) || 0)),
    unlimited: controls.unlimited.checked,
    priority: Math.max(0, Math.trunc(Number(controls.priority.value) || 0)),
    minimumHp: Math.max(0, Math.trunc(Number(controls.minimumHp.value) || 0)),
    gearSet: controls.gearSet.value,
    petSet: controls.petSet.value,
    staminaPotion: controls.staminaPotion.value,
    allowAbilities: controls.allowAbilities.checked,
    enabled: controls.enabled.checked,
  };
  const result = await updateCanonicalConfig({
    monsters: { maps: { [areaKey]: { [monsterKey]: entry } } },
  });
  if (result?.success) {
    monsterConfig = result.config?.monsters || monsterConfig;
  } else {
    appendLog('ERROR', result?.error || `Could not save ${name} configuration`);
  }
}

let cubePvpTargetOverview = null;
let cubePvpTargetConfig = {};

function cubePvpCooldownLabel(milliseconds) {
  const remaining = Math.max(0, Number(milliseconds) || 0);
  if (remaining <= 0) return 'Ready';
  const totalMinutes = Math.ceil(remaining / 60000);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return hours > 0 ? `${hours}h ${minutes}m` : `${minutes}m`;
}

async function saveCubePvpTargetPolicy(nodeId, patch) {
  const result = await updateCanonicalConfig({ cubePvp: { nodes: { [String(nodeId)]: patch } } });
  if (!result?.success) {
    appendLog('ERROR', result?.error || 'Could not save Cube PvP match policy');
    return false;
  }
  cubePvpTargetConfig = result.config?.cubePvp || cubePvpTargetConfig;
  const node = cubePvpTargetOverview?.nodes?.find(entry => Number(entry.id) === Number(nodeId));
  const policy = cubePvpTargetConfig.nodes?.[String(nodeId)];
  if (node && policy) {
    node.enabled = policy.enabled === true;
    node.matches = (node.matches || []).map(match => ({
      ...match,
      enabled: policy.matches?.[String(match.matchNo)]?.enabled !== false,
      priority: Number(policy.matches?.[String(match.matchNo)]?.priority) || 0,
    }));
    renderCubePvpTargets(cubePvpTargetOverview);
  }
  return true;
}

function renderCubePvpTargets(overview) {
  if (!cubePvpTargetContent) return;
  const nodes = overview?.nodes || [];
  if (cubePvpTargetStatus) {
    const enabledNodes = nodes.filter(node => node.enabled === true).length;
    cubePvpTargetStatus.textContent = !overview?.moduleSelected
      ? uiText('Select Module: Dungeons and Dungeon: Cube to run Cube PvP.')
      : cubePvpTargetConfig.enabled !== true
        ? uiText('Cube PvP is off. Enable Join Cube PvP, then press Apply or Start.')
        : enabledNodes === 0
          ? uiText('Enable at least one Cube PvP node below.')
          : uiText("{0} open match(es) · {1} enabled node(s)", nodes.reduce((total, node) => total + Number(node.openCount || 0), 0), enabledNodes);
  }
  const fragment = document.createDocumentFragment();
  for (const node of nodes) {
    const details = document.createElement('details');
    details.className = 'cube-pvp-node';
    const summary = document.createElement('summary');
    const chevron = createLucideIcon('chevron-right');
    chevron.classList.add('cube-pvp-node-chevron');
    const title = document.createElement('strong');
    title.textContent = `${node.name} [${Number(node.openCount) || 0}/${node.maximumMatches}]`;
    const state = document.createElement('span');
    state.className = `cube-pvp-state cube-pvp-state-${node.status || 'hidden'}`;
    state.textContent = String(node.status || 'hidden').replaceAll('_', ' ');
    const enabled = document.createElement('input');
    enabled.type = 'checkbox';
    enabled.className = 'tree-checkbox';
    enabled.checked = node.enabled === true;
    enabled.title = uiText("Allow Veybot to join OPEN matches in {0}", node.name);
    enabled.setAttribute('aria-label', enabled.title);
    enabled.addEventListener('click', event => event.stopPropagation());
    enabled.addEventListener('change', () => saveCubePvpTargetPolicy(node.id, { enabled: enabled.checked }));
    const enabledLabel = document.createElement('span');
    enabledLabel.className = 'cube-pvp-node-enable';
    enabledLabel.textContent = uiText('Join');
    enabledLabel.title = enabled.title;
    enabledLabel.addEventListener('click', event => event.stopPropagation());
    summary.append(chevron, title, state, enabledLabel, enabled);
    details.append(summary);

    if (node.error && !node.matches?.length) {
      const message = document.createElement('div');
      message.className = 'empty-state compact-empty-state';
      message.textContent = node.error;
      details.append(message);
    } else {
      const table = document.createElement('div');
      table.className = 'cube-pvp-match-table';
      const header = document.createElement('div');
      header.className = 'cube-pvp-match-row cube-pvp-match-header';
      for (const label of [uiText('Match'), uiText('Status'), uiText('Players'), uiText('Priority'), uiText('Join')]) {
        const cell = document.createElement('span'); cell.textContent = label; header.append(cell);
      }
      table.append(header);
      for (const match of node.matches || []) {
        const row = document.createElement('div');
        row.className = `cube-pvp-match-row${match.joined ? ' is-current' : ''}`;
        const number = document.createElement('span'); number.textContent = `#${match.matchNo}${match.joined ? ' · joined' : ''}`;
        const matchState = document.createElement('span'); matchState.textContent = match.status;
        const players = document.createElement('span'); players.textContent = `${match.occupiedSlots}/${match.maximumSlots}`;
        const priority = document.createElement('input');
        priority.type = 'number'; priority.min = '0'; priority.step = '1'; priority.className = 'monster-number-input';
        priority.value = String(match.priority || 0); priority.title = uiText('Lower numbers join first. Equal priorities use the smallest match number.');
        const allow = document.createElement('input');
        allow.type = 'checkbox'; allow.className = 'tree-checkbox'; allow.checked = match.enabled !== false;
        allow.title = uiText("Allow joining match #{0}", match.matchNo);
        const save = () => saveCubePvpTargetPolicy(node.id, {
          matches: { [String(match.matchNo)]: { enabled: allow.checked, priority: Math.max(0, Math.trunc(Number(priority.value) || 0)) } },
        });
        priority.addEventListener('change', save);
        allow.addEventListener('change', save);
        row.append(number, matchState, players, priority, allow);
        table.append(row);
      }
      details.append(table);
    }
    fragment.append(details);
  }
  cubePvpTargetContent.replaceChildren(fragment);
  enhanceNumberInputs(cubePvpTargetContent);
  refreshLucideIcons(cubePvpTargetContent);
}

async function refreshCubePvpTargets(force = false) {
  if (!cubePvpTargetContent || !activeAccount) return;
  const requestToken = accountRequestToken();
  cubePvpTargetContent.replaceChildren(Object.assign(document.createElement('div'), { className: 'empty-state', textContent: uiText('Loading Cube PvP matches…') }));
  if (btnRefreshCubePvpTargets) btnRefreshCubePvpTargets.disabled = true;
  try {
    const [result, config] = await Promise.all([window.botAPI.getCubePvpOverview(force === true), window.botAPI.getConfig()]);
    if (!isCurrentAccountRequest(requestToken)) return;
    if (!result?.success) throw new Error(result?.error || uiText('Cube PvP matches are unavailable'));
    cubePvpTargetConfig = config?.cubePvp || {};
    cubePvpTargetOverview = result.overview;
    if (result.overview?.status) renderCubePvpStatus(result.overview.status);
    renderCubePvpTargets(cubePvpTargetOverview);
  } catch (error) {
    if (!isCurrentAccountRequest(requestToken)) return;
    cubePvpTargetOverview = null;
    cubePvpTargetContent.replaceChildren(Object.assign(document.createElement('div'), { className: 'empty-state', textContent: error.message }));
    if (cubePvpTargetStatus) cubePvpTargetStatus.textContent = uiText('Cube PvP discovery failed.');
  } finally {
    if (isCurrentAccountRequest(requestToken) && btnRefreshCubePvpTargets) btnRefreshCubePvpTargets.disabled = false;
  }
}

function updateCubePvpTargetVisibility(areaKey, refresh = false) {
  const visible = areaKey === 'polyhedral_crucible';
  if (cubePvpTargetPanel) cubePvpTargetPanel.style.display = visible ? '' : 'none';
  if (visible && (refresh || !cubePvpTargetOverview)) refreshCubePvpTargets();
}

function renderMonsterArea(area, discovered = [], sourceAvailable = true, message = '') {
  if (!monsterAreaContent) return;
  const saved = monsterConfig.maps?.[area.key] || {};
  const merged = new Map(discovered.map(monster => [monster.key, monster]));
  Object.entries(saved).forEach(([key, entry]) => {
    if (!merged.has(key)) merged.set(key, { key, name: entry.name, boss: false, instances: 0, savedOnly: true });
  });

  if (!sourceAvailable && merged.size === 0) {
    const empty = document.createElement('div');
    empty.className = 'empty-config-panel compact-empty-config';
    const title = document.createElement('strong');
    title.textContent = uiText("{0} is currently unavailable", area.label);
    const detail = document.createElement('span');
    detail.textContent = message || uiText('Monster discovery will retry automatically when this account can access the area.');
    empty.append(title, detail);
    monsterAreaContent.replaceChildren(empty);
    return;
  }

  if (merged.size === 0) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.textContent = message || uiText("No monster types were found for {0}.", area.label);
    monsterAreaContent.replaceChildren(empty);
    return;
  }

  const table = document.createElement('div');
  table.className = 'monster-config-table';
  const header = document.createElement('div');
  header.className = 'monster-config-row monster-config-header';
  for (const [label, title] of [
    [uiText('Monster'), uiText('Monster Name')], [uiText('Alive'), uiText('Currently alive / total discovered')], [uiText('Stats'), uiText('Monster stats')], [uiText('Damage'), uiText('Target damage')], [uiText('Kills'), uiText('Total kill count')], [uiText('Per dungeon'), uiText('Dungeon only: maximum completed targets of this type in each dungeon instance; 0 disables this separate limit')], ['∞', uiText('Unlimited targets')],
    [uiText('Pri'), uiText('Priority — lower numbers run first')], [uiText('Min HP'), uiText('Minimum HP')],
    [uiText('Done'), uiText('Completed target count')], [uiText('Gear'), uiText('Gear set')], [uiText('Pet'), uiText('Pet set')],
    [uiText('Potions'), uiText('Stamina potion selection')], [uiText('Skills'), uiText('Allow all globally enabled abilities for this monster')], [uiText('Target'), uiText('Target enabled')],
  ]) {
    const cell = document.createElement('span');
    cell.textContent = label;
    cell.title = uiText(title);
    header.appendChild(cell);
  }
  table.appendChild(header);

  for (const monster of [...merged.values()].sort((left, right) => left.name.localeCompare(right.name))) {
    const stored = saved[monster.key] || {};
    const row = document.createElement('div');
    row.className = 'monster-config-row';
    row.dataset.monsterKey = monster.key;
    row.dataset.monsterName = monster.name;
    const name = document.createElement('div');
    name.className = 'monster-config-name';
    const nameText = document.createElement('span');
    nameText.className = 'monster-config-name-text';
    nameText.textContent = monster.name;
    name.appendChild(nameText);
    if (monster.phase) {
      const badge = document.createElement('span');
      badge.className = 'monster-phase-badge';
      badge.textContent = uiText("Phase {0}", monster.phase);
      name.appendChild(badge);
    } else if (monster.boss) {
      const badge = document.createElement('span');
      badge.className = 'monster-boss-badge';
      badge.textContent = uiText('Boss');
      name.appendChild(badge);
    }
    const availability = document.createElement('span');
    availability.className = 'monster-availability-count';
    const aliveCount = Math.max(0, Number(monster.aliveCount ?? monster.instances) || 0);
    const totalCount = Math.max(aliveCount, Number(monster.totalCount ?? monster.instances) || 0);
    availability.textContent = `${aliveCount}/${totalCount}`;
    availability.title = uiText("{0} currently alive out of {1} discovered", aliveCount, totalCount);
    const statsButton = document.createElement('button');
    statsButton.type = 'button';
    statsButton.className = `monster-stats-help${monster.statsAvailable ? ' has-stats' : ''}`;
    statsButton.append(createLucideIcon('circle-help'));
    statsButton.title = uiText("View verified stats for {0}", monster.name);
    statsButton.setAttribute('aria-label', uiText("View {0} stats", monster.name));
    statsButton.addEventListener('click', () => monsterStatsView?.open(area.key, monster.key, monster.name));

    const targetDamage = document.createElement('input');
    targetDamage.type = 'number';
    targetDamage.min = '0';
    targetDamage.step = '1';
    targetDamage.value = stored.targetDamage ?? 0;
    targetDamage.className = 'monster-number-input';
    targetDamage.setAttribute('aria-label', uiText("{0} target damage", monster.name));

    const killCount = document.createElement('input');
    killCount.type = 'number';
    killCount.min = '0';
    killCount.step = '1';
    killCount.value = stored.killCount ?? 0;
    killCount.className = 'monster-number-input';
    killCount.setAttribute('aria-label', uiText("{0} kill count", monster.name));

    let dungeonKillCount;
    if (area.type === 'dungeon') {
      dungeonKillCount = document.createElement('input');
      dungeonKillCount.type = 'number';
      dungeonKillCount.min = '0';
      dungeonKillCount.step = '1';
      dungeonKillCount.value = stored.dungeonKillCount ?? 0;
      dungeonKillCount.className = 'monster-number-input';
      dungeonKillCount.title = uiText('Maximum targets of this type to complete in each dungeon instance. It resets automatically for a new instance. 0 uses the ordinary Kills limit.');
      dungeonKillCount.setAttribute('aria-label', uiText("{0} per-dungeon kill count", monster.name));
    } else {
      dungeonKillCount = document.createElement('span');
      dungeonKillCount.textContent = '—';
      dungeonKillCount.title = uiText('Per-dungeon limits apply only to Dungeon areas.');
    }

    const unlimited = document.createElement('input');
    unlimited.type = 'checkbox';
    unlimited.className = 'tree-checkbox monster-unlimited';
    unlimited.checked = stored.unlimited === true;
    unlimited.title = uiText('Keep targeting new instances without a kill-count limit.');
    unlimited.setAttribute('aria-label', uiText("Unlimited targets for {0}", monster.name));
    const updateTargetLimitState = () => {
      killCount.disabled = unlimited.checked;
      killCount.classList.toggle('module-setting-disabled', unlimited.checked);
    };
    updateTargetLimitState();

    const priority = document.createElement('input');
    priority.type = 'number';
    priority.min = '0';
    priority.step = '1';
    priority.value = stored.priority ?? 0;
    priority.className = 'monster-number-input';
    priority.title = uiText('Lower numbers are targeted first; equal priorities sort by monster name.');
    priority.setAttribute('aria-label', uiText("{0} target priority", monster.name));

    const minimumHp = document.createElement('input');
    minimumHp.type = 'number';
    minimumHp.min = '0';
    minimumHp.step = '1';
    minimumHp.value = stored.minimumHp ?? 0;
    minimumHp.className = 'monster-number-input';
    minimumHp.title = uiText('Ignore an instance when its current HP is below this value.');
    minimumHp.setAttribute('aria-label', uiText("{0} minimum current HP", monster.name));

    const progress = document.createElement('div');
    progress.className = 'monster-progress';
    const progressText = document.createElement('span');
    progressText.textContent = `${stored.completedCount || 0}/${stored.unlimited === true ? '∞' : (stored.killCount || 0)}`;
    const resetProgress = document.createElement('button');
    resetProgress.type = 'button';
    resetProgress.className = 'monster-progress-reset';
    resetProgress.append(createLucideIcon('rotate-ccw'));
    resetProgress.title = uiText("Reset completed target count for {0}", monster.name);
    resetProgress.addEventListener('click', async () => {
      const result = await updateCanonicalConfig({
        monsters: { maps: { [area.key]: { [monster.key]: { completedCount: 0, completedInstanceIds: [] } } } },
      });
      if (result?.success) {
        monsterConfig = result.config?.monsters || monsterConfig;
        progressText.textContent = `0/${unlimited.checked ? '∞' : (killCount.value || 0)}`;
      } else {
        appendLog('ERROR', result?.error || `Could not reset ${monster.name} progress`);
      }
    });
    progress.append(progressText, resetProgress);

    const gearSet = createMonsterSetSelect(stored.gearSet, `${monster.name} Gear set`);
    const petSet = createMonsterSetSelect(stored.petSet, `${monster.name} Pet set`);
    const staminaPotion = createStaminaPotionSelect(stored.staminaPotion, `${monster.name} stamina potion`);
    const allowAbilities = document.createElement('input');
    allowAbilities.type = 'checkbox';
    allowAbilities.className = 'tree-checkbox monster-abilities';
    allowAbilities.checked = stored.allowAbilities === true;
    allowAbilities.title = uiText('Off by default. When enabled, all abilities allowed in Combat may be used against this monster; individual per-monster ability selection is intentionally unavailable.');
    allowAbilities.setAttribute('aria-label', uiText("Allow abilities against {0}", monster.name));
    const enabled = document.createElement('input');
    enabled.type = 'checkbox';
    enabled.className = 'tree-checkbox monster-enabled';
    enabled.checked = stored.enabled === true;
    enabled.title = uiText('Include this monster type as an automation target.');
    enabled.setAttribute('aria-label', uiText("Target {0}", monster.name));

    const controls = { targetDamage, killCount, dungeonKillCount: area.type === 'dungeon' ? dungeonKillCount : null, unlimited, priority, minimumHp, gearSet, petSet, staminaPotion, allowAbilities, enabled };
    Object.values(controls).filter(Boolean).forEach(control => {
      control.addEventListener('change', () => {
        saveMonsterRow(area.key, monster.key, monster.name, controls);
      });
    });
    killCount.addEventListener('change', () => {
      progressText.textContent = `${stored.completedCount || 0}/${unlimited.checked ? '∞' : (killCount.value || 0)}`;
    });
    unlimited.addEventListener('change', () => {
      updateTargetLimitState();
      progressText.textContent = `${stored.completedCount || 0}/${unlimited.checked ? '∞' : (killCount.value || 0)}`;
    });
    row.append(name, availability, statsButton, targetDamage, killCount, dungeonKillCount, unlimited, priority, minimumHp, progress, gearSet, petSet, staminaPotion, allowAbilities, enabled);
    enhanceNumberInputs(row);
    table.appendChild(row);
  }

  monsterAreaContent.replaceChildren(table);
  refreshLucideIcons(monsterAreaContent);
}

async function setAllVisibleTargets(field, value) {
  const areaKey = activeMonsterAreaKey;
  if (!areaKey) return;
  const patch = {};
  for (const row of monsterAreaContent?.querySelectorAll('.monster-config-row[data-monster-key]') || []) {
    patch[row.dataset.monsterKey] = { name: row.dataset.monsterName || row.dataset.monsterKey, [field]: value };
    const checkbox = row.querySelector(field === 'unlimited' ? '.monster-unlimited' : '.monster-enabled');
    if (checkbox) checkbox.checked = value;
  }
  if (Object.keys(patch).length === 0) return;
  const result = await updateCanonicalConfig({ monsters: { maps: { [areaKey]: patch } } });
  if (!result?.success) {
    appendLog('ERROR', result?.error || 'Could not update visible targets');
    return;
  }
  monsterConfig = result.config?.monsters || monsterConfig;
  await selectMonsterArea(areaKey, true);
}

btnTargetUnlimitedAll?.addEventListener('click', () => setAllVisibleTargets('unlimited', true));
btnTargetEnableAll?.addEventListener('click', () => setAllVisibleTargets('enabled', true));

async function selectMonsterArea(areaKey, force = false) {
  const area = monsterCatalog.find(candidate => candidate.key === areaKey);
  if (!area || !monsterAreaContent) return;
  if (force) {
    const latestConfig = await window.botAPI.getConfig();
    monsterConfig = latestConfig?.monsters || monsterConfig;
  }
  activeMonsterAreaKey = areaKey;
  if (targetAreaSelect) targetAreaSelect.value = areaKey;
  if (targetAreaTypeSelect) targetAreaTypeSelect.value = areaWorkspaceType(area);

  if (!force && monsterAreaCache.has(areaKey)) {
    const cached = monsterAreaCache.get(areaKey);
    renderMonsterArea(area, cached.monsters, cached.sourceAvailable, cached.message);
    updateCubePvpTargetVisibility(areaKey, false);
    return;
  }

  monsterAreaContent.innerHTML = ("<div class=\"empty-state\">" + uiText("Loading monster types…") + "</div>");
  const result = await window.botAPI.listMonstersForArea(areaKey, force);
  if (!result?.success) {
    renderMonsterArea(area, [], true, result?.error || 'Monster discovery failed.');
    updateCubePvpTargetVisibility(areaKey, force);
    return;
  }
  monsterAreaCache.set(areaKey, result);
  renderMonsterArea(area, result.monsters || [], result.sourceAvailable !== false, result.message || '');
  updateCubePvpTargetVisibility(areaKey, force);
}

async function loadMonsterWorkspace(force = false) {
  const latestConfig = await window.botAPI.getConfig();
  monsterConfig = latestConfig?.monsters || monsterConfig;
  if (monsterCatalog.length === 0) {
    monsterCatalog = await window.botAPI.getMonsterCatalog();
  }
  const configuredAreaKey = preferredBotSetupArea();
  const configuredArea = monsterCatalog.find(area => area.key === configuredAreaKey);
  if (configuredArea) activeMonsterAreaKey = configuredArea.key;
  const selectedArea = configuredArea || monsterCatalog.find(area => area.key === activeMonsterAreaKey);
  const selectedType = (selectedArea && areaWorkspaceType(selectedArea))
    || targetAreaTypeSelect?.value
    || 'gate';
  if (targetAreaTypeSelect) targetAreaTypeSelect.value = selectedType;
  activeMonsterAreaKey = populateTargetAreaSelect(selectedType, activeMonsterAreaKey);
  if (activeMonsterAreaKey) await selectMonsterArea(activeMonsterAreaKey, force);
}

if (targetAreaSelect) {
  targetAreaSelect.addEventListener('change', () => selectMonsterArea(targetAreaSelect.value));
}
if (targetAreaTypeSelect) {
  targetAreaTypeSelect.addEventListener('change', async () => {
    activeMonsterAreaKey = populateTargetAreaSelect(targetAreaTypeSelect.value);
    if (activeMonsterAreaKey) await selectMonsterArea(activeMonsterAreaKey);
  });
}

if (btnRefreshMonsterArea) {
  btnRefreshMonsterArea.addEventListener('click', async () => {
    if (!activeMonsterAreaKey) return;
    btnRefreshMonsterArea.disabled = true;
    try {
      await selectMonsterArea(activeMonsterAreaKey, true);
    } finally {
      btnRefreshMonsterArea.disabled = false;
    }
  });
}

btnRefreshCubePvpTargets?.addEventListener('click', () => refreshCubePvpTargets(true));

if (btnCollectMonsterStats) {
  btnCollectMonsterStats.addEventListener('click', async () => {
    if (!activeMonsterAreaKey) return;
    btnCollectMonsterStats.disabled = true;
    const previousText = btnCollectMonsterStats.textContent;
    btnCollectMonsterStats.textContent = uiText('Collecting…');
    try {
      const result = await window.botAPI.collectMonsterStatsForArea(activeMonsterAreaKey);
      if (!result?.success) throw new Error(result?.error || uiText('Monster Stats collection failed'));
      const details = `${result.collected} read, ${result.conflicts} conflicts, ${result.errors?.length || 0} errors`;
      appendLog(result.errors?.length || result.conflicts ? 'WARN' : 'INFO', `Monster Stats: ${details}`);
      monsterAreaCache.delete(activeMonsterAreaKey);
      await selectMonsterArea(activeMonsterAreaKey, true);
    } catch (error) {
      appendLog('ERROR', error.message);
    } finally {
      btnCollectMonsterStats.disabled = false;
      btnCollectMonsterStats.textContent = previousText;
    }
  });
}
async function saveLootRow(areaKey, monsterKey, name, controls) {
  const entry = {
    name,
    priority: nonNegativeInputValue(controls.priority),
    maxLooting: nonNegativeInputValue(controls.maxLooting),
    unlimited: Boolean(controls.unlimited.checked),
    enabled: Boolean(controls.enabled.checked),
  };
  const result = await updateCanonicalConfig({
    looting: { maps: { [areaKey]: { [monsterKey]: entry } } },
  });
  if (result?.success) {
    lootingConfig = result.config?.looting || lootingConfig;
  } else {
    appendLog('ERROR', result?.error || `Could not save ${name} loot priority`);
  }
}

function renderLootArea(area, discovered = [], sourceAvailable = true, message = '') {
  if (!lootAreaContent) return;
  const savedTargets = monsterConfig.maps?.[area.key] || {};
  const savedLoot = lootingConfig.maps?.[area.key] || {};
  const merged = new Map(discovered.map(monster => [monster.key, monster]));
  for (const [key, entry] of Object.entries(savedTargets)) {
    if (!merged.has(key)) merged.set(key, { key, name: entry.name, boss: false, savedOnly: true });
  }
  for (const [key, entry] of Object.entries(savedLoot)) {
    if (!merged.has(key)) merged.set(key, { key, name: entry.name, boss: false, savedOnly: true });
  }

  if (merged.size === 0) {
    const empty = document.createElement('div');
    empty.className = sourceAvailable ? 'empty-state' : 'empty-config-panel compact-empty-config';
    empty.textContent = message || (sourceAvailable
      ? uiText("No monster types were found for {0}.", area.label)
      : uiText('Dungeon monster discovery requires an active dungeon instance.'));
    lootAreaContent.replaceChildren(empty);
    return;
  }

  const table = document.createElement('div');
  table.className = 'loot-config-table';
  const header = document.createElement('div');
  header.className = 'loot-config-row loot-config-header';
  for (const label of ['Monster', 'Lootable', 'Priority', 'Max looting', '∞', 'Done', 'Loot']) {
    const cell = document.createElement('span');
    cell.textContent = label;
    header.appendChild(cell);
  }
  table.appendChild(header);
  for (const monster of [...merged.values()].sort((left, right) => left.name.localeCompare(right.name))) {
    const stored = savedLoot[monster.key] || {};
    const row = document.createElement('div');
    row.className = 'loot-config-row';
    row.dataset.monsterKey = monster.key;
    row.dataset.monsterName = monster.name;
    const name = document.createElement('div');
    name.className = 'monster-config-name';
    name.textContent = monster.name;
    if (monster.phase) {
      const badge = document.createElement('span');
      badge.className = 'monster-phase-badge';
      badge.textContent = uiText("Phase {0}", monster.phase);
      name.appendChild(badge);
    } else if (monster.boss) {
      const badge = document.createElement('span');
      badge.className = 'monster-boss-badge';
      badge.textContent = uiText('Boss');
      name.appendChild(badge);
    }
    const lootable = document.createElement('span');
    lootable.className = 'lootable-count';
    lootable.textContent = Number.isFinite(Number(monster.lootableCount)) ? String(monster.lootableCount) : '—';
    lootable.title = uiText("{0} currently available to loot", monster.name);
    const priority = document.createElement('input');
    priority.type = 'number';
    priority.min = '0';
    priority.step = '1';
    priority.value = stored.priority ?? 0;
    priority.className = 'monster-number-input loot-priority-input';
    priority.title = uiText('Lower numbers are looted first; equal priorities sort by monster name.');
    priority.setAttribute('aria-label', uiText("{0} loot priority", monster.name));
    const maxLooting = document.createElement('input');
    maxLooting.type = 'number';
    maxLooting.min = '0';
    maxLooting.step = '1';
    maxLooting.value = stored.maxLooting ?? 0;
    maxLooting.className = 'monster-number-input loot-limit-input';
    maxLooting.setAttribute('aria-label', uiText("{0} maximum looting count", monster.name));
    const unlimited = document.createElement('input');
    unlimited.type = 'checkbox';
    unlimited.className = 'tree-checkbox loot-unlimited';
    unlimited.checked = stored.unlimited === true;
    unlimited.title = uiText('Allow looting without a count limit.');
    unlimited.setAttribute('aria-label', uiText("Unlimited looting for {0}", monster.name));
    const updateLootLimitState = () => {
      maxLooting.disabled = unlimited.checked;
      maxLooting.classList.toggle('module-setting-disabled', unlimited.checked);
    };
    updateLootLimitState();
    const progress = document.createElement('div');
    progress.className = 'monster-progress';
    const progressText = document.createElement('span');
    progressText.textContent = `${stored.lootedCount || 0}/${stored.unlimited === true ? '∞' : (stored.maxLooting || 0)}`;
    const resetProgress = document.createElement('button');
    resetProgress.type = 'button';
    resetProgress.className = 'monster-progress-reset';
    resetProgress.append(createLucideIcon('rotate-ccw'));
    resetProgress.title = uiText("Reset looted count for {0}", monster.name);
    resetProgress.addEventListener('click', async () => {
      const result = await updateCanonicalConfig({
        looting: { maps: { [area.key]: { [monster.key]: { lootedCount: 0, lootedInstanceIds: [] } } } },
      });
      if (result?.success) {
        lootingConfig = result.config?.looting || lootingConfig;
        progressText.textContent = `0/${unlimited.checked ? '∞' : (maxLooting.value || 0)}`;
      } else {
        appendLog('ERROR', result?.error || `Could not reset ${monster.name} loot progress`);
      }
    });
    progress.append(progressText, resetProgress);
    const enabled = document.createElement('input');
    enabled.type = 'checkbox';
    enabled.className = 'tree-checkbox loot-enabled';
    enabled.checked = stored.enabled === true;
    enabled.setAttribute('aria-label', uiText("Enable looting {0}", monster.name));
    const controls = { priority, maxLooting, unlimited, enabled };
    Object.values(controls).forEach(control => {
      control.addEventListener('change', () => saveLootRow(area.key, monster.key, monster.name, controls));
    });
    unlimited.addEventListener('change', () => {
      updateLootLimitState();
      progressText.textContent = `${stored.lootedCount || 0}/${unlimited.checked ? '∞' : (maxLooting.value || 0)}`;
    });
    maxLooting.addEventListener('change', () => {
      progressText.textContent = `${stored.lootedCount || 0}/${unlimited.checked ? '∞' : (maxLooting.value || 0)}`;
    });
    row.append(name, lootable, priority, maxLooting, unlimited, progress, enabled);
    enhanceNumberInputs(row);
    table.appendChild(row);
  }
  lootAreaContent.replaceChildren(table);
  refreshLucideIcons(lootAreaContent);
}

async function setAllVisibleLoot(field, value) {
  const areaKey = activeLootAreaKey;
  if (!areaKey) return;
  const patch = {};
  for (const row of lootAreaContent?.querySelectorAll('.loot-config-row[data-monster-key]') || []) {
    patch[row.dataset.monsterKey] = { name: row.dataset.monsterName || row.dataset.monsterKey, [field]: value };
    const checkbox = row.querySelector(field === 'unlimited' ? '.loot-unlimited' : '.loot-enabled');
    if (checkbox) checkbox.checked = value;
  }
  if (Object.keys(patch).length === 0) return;
  const result = await updateCanonicalConfig({ looting: { maps: { [areaKey]: patch } } });
  if (!result?.success) {
    appendLog('ERROR', result?.error || 'Could not update visible loot settings');
    return;
  }
  lootingConfig = result.config?.looting || lootingConfig;
  await selectLootArea(areaKey, true);
}

btnLootUnlimitedAll?.addEventListener('click', () => setAllVisibleLoot('unlimited', true));
btnLootEnableAll?.addEventListener('click', () => setAllVisibleLoot('enabled', true));

async function selectLootArea(areaKey, force = false) {
  const area = monsterCatalog.find(candidate => candidate.key === areaKey);
  if (!area || !lootAreaContent) return;
  if (force) {
    const latestConfig = await window.botAPI.getConfig();
    monsterConfig = latestConfig?.monsters || monsterConfig;
    lootingConfig = latestConfig?.looting || lootingConfig;
  }
  activeLootAreaKey = areaKey;
  if (lootAreaSelect) lootAreaSelect.value = areaKey;
  if (lootAreaTypeSelect) lootAreaTypeSelect.value = areaWorkspaceType(area);

  if (!force && lootAreaCache.has(areaKey)) {
    const cached = lootAreaCache.get(areaKey);
    renderLootArea(area, cached.monsters, cached.sourceAvailable, cached.message);
    return;
  }

  lootAreaContent.innerHTML = ("<div class=\"empty-state\">" + uiText("Loading monster types…") + "</div>");
  const result = await window.botAPI.listLootableMonstersForArea(areaKey);
  if (!result?.success) {
    renderLootArea(area, [], true, result?.error || 'Monster discovery failed.');
    return;
  }
  lootAreaCache.set(areaKey, result);
  renderLootArea(area, result.monsters || [], result.sourceAvailable !== false, result.message || '');
}

async function loadLootWorkspace(force = false) {
  const latestConfig = await window.botAPI.getConfig();
  monsterConfig = latestConfig?.monsters || monsterConfig;
  lootingConfig = latestConfig?.looting || lootingConfig;
  if (monsterCatalog.length === 0) monsterCatalog = await window.botAPI.getMonsterCatalog();
  const configuredAreaKey = preferredBotSetupArea();
  const configuredArea = monsterCatalog.find(area => area.key === configuredAreaKey);
  if (configuredArea) activeLootAreaKey = configuredArea.key;
  const selectedArea = configuredArea || monsterCatalog.find(area => area.key === activeLootAreaKey);
  const selectedType = (selectedArea && areaWorkspaceType(selectedArea))
    || lootAreaTypeSelect?.value
    || 'gate';
  if (lootAreaTypeSelect) lootAreaTypeSelect.value = selectedType;
  activeLootAreaKey = populateLootAreaSelect(selectedType, activeLootAreaKey);
  if (activeLootAreaKey) await selectLootArea(activeLootAreaKey, force);
}

if (lootAreaSelect) lootAreaSelect.addEventListener('change', () => selectLootArea(lootAreaSelect.value));
if (lootAreaTypeSelect) {
  lootAreaTypeSelect.addEventListener('change', async () => {
    activeLootAreaKey = populateLootAreaSelect(lootAreaTypeSelect.value);
    if (activeLootAreaKey) await selectLootArea(activeLootAreaKey);
  });
}
if (btnRefreshLootArea) {
  btnRefreshLootArea.addEventListener('click', async () => {
    if (!activeLootAreaKey) return;
    btnRefreshLootArea.disabled = true;
    try {
      await selectLootArea(activeLootAreaKey, true);
    } finally {
      btnRefreshLootArea.disabled = false;
    }
  });
}

window.switchHomeSubTab = function (subtab) {
  const tabs = { general: subtabHomeGeneralBtn, bot: subtabHomeBotBtn };
  const views = { general: subviewHomeGeneral, equipment: subviewHomeEquipment, bot: subviewHomeBot };
  Object.entries(tabs).forEach(([name, button]) => button?.classList.toggle('active', name === subtab));
  Object.entries(views).forEach(([name, view]) => { if (view) view.style.display = name === subtab ? 'flex' : 'none'; });
  if (subtab === 'equipment') {
    renderCombatPlayerStats();
    refreshCombatData(false);
  }
};

document.querySelectorAll('[data-home-tab]').forEach(button => {
  button.addEventListener('click', () => window.switchHomeSubTab(button.dataset.homeTab));
});
// Account-scoped Statistics read model. This view performs no game-network discovery.
let statisticsRequestGeneration = 0;

function statisticsTable(headers, rows, emptyMessage) {
  const table = document.createElement('div');
  table.className = 'statistics-table';
  if (!rows.length) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.textContent = emptyMessage;
    table.append(empty);
    return table;
  }
  const header = document.createElement('div');
  header.className = 'statistics-table-row statistics-table-header';
  for (const label of headers) {
    const cell = document.createElement('span');
    cell.textContent = label;
    header.append(cell);
  }
  table.append(header);
  for (const values of rows) {
    const row = document.createElement('div');
    row.className = 'statistics-table-row';
    for (const value of values) {
      const cell = document.createElement('span');
      cell.textContent = String(value ?? '-');
      cell.title = cell.textContent;
      row.append(cell);
    }
    table.append(row);
  }
  return table;
}

function replaceStatisticsTable(container, headers, rows, emptyMessage) {
  if (!container) return;
  container.replaceChildren(statisticsTable(headers, rows, emptyMessage));
}

function statisticsResourceLabel(row = {}) {
  const resource = row.resource ? uiText(row.resource.charAt(0).toUpperCase() + row.resource.slice(1)) : uiText('Resource');
  const potion = row.potionType ? uiText(row.potionType.charAt(0).toUpperCase() + row.potionType.slice(1)) : '';
  if (row.type === 'potion_use') return uiText('{0} potion used{1}', resource, potion ? ' · ' + potion : '');
  if (row.type === 'potion_purchase') return uiText('{0} potion purchased', resource);
  if (row.type === 'chapter_farm') return uiText('Chapter farmed');
  if (row.type === 'healing') return row.potionType ? uiText('Health potion healing') : uiText('Timed healing');
  return uiText(String(row.type || 'Activity').replaceAll('_', ' '));
}

function renderStatisticsTrend(trend = []) {
  if (!statisticsTrend) return;
  statisticsTrend.replaceChildren();
  const maxAttacks = Math.max(1, ...trend.map(row => Number(row.attacks) || 0));
  const maxClaims = Math.max(1, ...trend.map(row => Number(row.claims) || 0));
  for (const row of trend) {
    const column = document.createElement('div');
    column.className = 'statistics-trend-column';
    const bars = document.createElement('div');
    bars.className = 'statistics-trend-bars';
    const attacks = document.createElement('span');
    attacks.className = 'statistics-trend-bar statistics-trend-attacks';
    attacks.style.height = `${Math.max(2, Math.round(((Number(row.attacks) || 0) / maxAttacks) * 62))}px`;
    attacks.title = uiText("{0} attacks", formatNumber(row.attacks));
    const loot = document.createElement('span');
    loot.className = 'statistics-trend-bar statistics-trend-loot';
    loot.style.height = `${Math.max(2, Math.round(((Number(row.claims) || 0) / maxClaims) * 62))}px`;
    loot.title = uiText("{0} loot claims", formatNumber(row.claims));
    bars.append(attacks, loot);
    const label = document.createElement('span');
    label.className = 'statistics-trend-label';
    const date = new Date(`${row.date}T00:00:00Z`);
    label.textContent = Number.isNaN(date.getTime()) ? row.date : `${date.getUTCMonth() + 1}/${date.getUTCDate()}`;
    column.append(bars, label);
    statisticsTrend.append(column);
  }
}

function resetStatisticsView() {
  statisticsRequestGeneration += 1;
  for (const element of [statisticsAttacks, statisticsReached, statisticsStamina,
    statisticsClaims, statisticsXp, statisticsGold, statisticsItems, statisticsPvpJoined, statisticsPvpWins, statisticsPvpLosses,
    statisticsAverageStamina, statisticsAverageXp, statisticsPotionsUsed, statisticsChapters, statisticsHeals]) {
    if (element) element.textContent = '0';
  }
  if (statisticsReachRate) statisticsReachRate.textContent = '0%';
  if (statisticsPvpDuration) statisticsPvpDuration.textContent = '—';
  for (const container of [statisticsTrend, statisticsCombatTable, statisticsLootTable,
    statisticsResourcesTable, statisticsItemsTable, statisticsPvpTable, statisticsAreasTable]) {
    container?.replaceChildren();
  }
  setWorkspaceStatus(statisticsStatus, uiText('Select a period to inspect saved account activity.'));
}

function renderStatistics(data = {}) {
  const summary = data.summary || {};
  const values = new Map([
    [statisticsAttacks, summary.attacks],
    [statisticsReached, summary.targetsReached],
    [statisticsStamina, summary.stamina],
    [statisticsClaims, summary.claims],
    [statisticsXp, summary.xp],
    [statisticsGold, summary.gold],
    [statisticsItems, summary.items],
    [statisticsPvpJoined, summary.pvpMatchesJoined],
    [statisticsPvpWins, summary.pvpWins],
    [statisticsPvpLosses, summary.pvpLosses],
    [statisticsPotionsUsed, summary.potionsUsed],
    [statisticsChapters, summary.chaptersFarmed],
    [statisticsHeals, summary.heals],
  ]);
  for (const [element, value] of values) if (element) element.textContent = formatNumber(value);
  const attacks = Math.max(0, Number(summary.attacks) || 0);
  const claims = Math.max(0, Number(summary.claims) || 0);
  if (statisticsReachRate) statisticsReachRate.textContent = `${attacks > 0 ? ((Number(summary.targetsReached) || 0) / attacks * 100).toFixed(1) : '0.0'}%`;
  if (statisticsAverageStamina) statisticsAverageStamina.textContent = formatNumber(attacks > 0 ? ((Number(summary.stamina) || 0) / attacks).toFixed(1) : 0);
  if (statisticsAverageXp) statisticsAverageXp.textContent = formatNumber(claims > 0 ? Math.round((Number(summary.xp) || 0) / claims) : 0);
  if (statisticsPvpDuration) {
    const averageSeconds = Number(summary.pvpCompleted) > 0 ? Math.round((Number(summary.pvpDurationMs) || 0) / Number(summary.pvpCompleted) / 1000) : 0;
    statisticsPvpDuration.textContent = averageSeconds > 0 ? uiText("{0}m {1}s", Math.floor(averageSeconds / 60), averageSeconds % 60) : '—';
  }
  renderStatisticsTrend(data.trend || []);

  replaceStatisticsTable(statisticsCombatTable,
    [uiText('Monster'), uiText('Area'), uiText('Hits'), uiText('Reached'), uiText('ST')],
    (data.combat || []).map(row => [row.monsterName, row.areaName, formatNumber(row.attacks),
      formatNumber(row.completedTargets), formatNumber(row.totalStamina)]),
    uiText('No recorded attacks in this period.'));
  replaceStatisticsTable(statisticsLootTable,
    [uiText('Monster'), uiText('Area'), uiText('Claims'), uiText('EXP'), uiText('Gold'), uiText('Items')],
    (data.loot || []).map(row => [row.monsterName, row.areaName, formatNumber(row.claims),
      formatNumber(row.totalXp), formatNumber(row.totalGold), formatNumber(row.itemsCount)]),
    uiText('No recorded loot claims in this period.'));
  replaceStatisticsTable(statisticsResourcesTable,
    [uiText('Activity'), uiText('Actions'), uiText('Quantity')],
    (data.resources || []).map(row => [statisticsResourceLabel(row), formatNumber(row.actions), formatNumber(row.quantity)]),
    uiText('No recorded resource activity in this period.'));
  replaceStatisticsTable(statisticsItemsTable,
    [uiText('Item'), uiText('Tier'), uiText('Quantity')],
    (data.items || []).map(row => [row.name, row.tier || '-', formatNumber(row.quantityObtained)]),
    uiText('No recorded item drops in this period.'));
  replaceStatisticsTable(statisticsPvpTable,
    [uiText('Time'), uiText('Node'), uiText('Match'), uiText('State'), uiText('Result'), uiText('Duration')],
    (data.pvp || []).map(event => [new Date(event.observedAt).toLocaleString(), event.details?.nodeName || `Node ${event.details?.nodeId || '-'}`,
      `#${event.details?.matchNo || '-'}`, event.details?.state || event.type.replace('cube_pvp_', ''), event.details?.winnerSide || '-',
      Number(event.details?.durationMs) > 0 ? `${Math.round(Number(event.details.durationMs) / 60000)}m` : '-']),
    uiText('No recorded Cube PvP activity in this period.'));
  replaceStatisticsTable(statisticsAreasTable,
    [uiText('Area'), uiText('Hits'), uiText('Reached'), uiText('ST'), uiText('Claims'), uiText('EXP'), uiText('Gold'), uiText('Items')],
    (data.areas || []).map(row => [row.areaName, formatNumber(row.attacks), formatNumber(row.targetsReached),
      formatNumber(row.stamina), formatNumber(row.claims), formatNumber(row.xp),
      formatNumber(row.gold), formatNumber(row.items)]),
    uiText('No recorded area activity in this period.'));

  const coverage = data.coverage || {};
  const limited = coverage.targetAtRetentionLimit || coverage.lootAtRetentionLimit || coverage.eventsAtRetentionLimit;
  const periodLabel = statisticsPeriod?.selectedOptions?.[0]?.textContent || data.period || uiText('Selected period');
  setWorkspaceStatus(statisticsStatus,
    uiText("{0} · {1} potions used · {2} chapters{3}", periodLabel, formatNumber(summary.potionsUsed), formatNumber(summary.chaptersFarmed), limited ? uiText(' · detailed history retention limit reached') : ''),
    limited ? 'warning' : 'success');
}

async function refreshStatistics() {
  if (!activeAccount || !statisticsPeriod) return;
  const generation = ++statisticsRequestGeneration;
  setRefreshBusy(btnRefreshStatistics, true);
  setWorkspaceStatus(statisticsStatus, uiText('Loading saved account statistics...'));
  try {
    const result = await withUiTimeout(window.botAPI.getStatistics(statisticsPeriod.value), 15000, uiText('Statistics'));
    if (generation !== statisticsRequestGeneration) return;
    if (!result?.success || !result.statistics) throw new Error(result?.error || uiText('Statistics are unavailable'));
    renderStatistics(result.statistics);
  } catch (error) {
    if (generation === statisticsRequestGeneration) setWorkspaceStatus(statisticsStatus, error.message, 'error');
  } finally {
    if (generation === statisticsRequestGeneration) setRefreshBusy(btnRefreshStatistics, false);
  }
}

statisticsPeriod?.addEventListener('change', refreshStatistics);
btnRefreshStatistics?.addEventListener('click', refreshStatistics);
const objectiveControlRequests = new WeakMap();
const objectiveMonsterReads = new Map();
let objectiveBoardGeneration = 0;

function objectiveRequest(select) {
  const generation = (objectiveControlRequests.get(select) || 0) + 1;
  objectiveControlRequests.set(select, generation);
  const account = accountRequestToken();
  return () => objectiveControlRequests.get(select) === generation
    && isCurrentAccountRequest(account) && select.isConnected !== false;
}

function readObjectiveMonsters(areaKey, force) {
  const account = accountRequestToken();
  const key = JSON.stringify([account.generation, account.account, areaKey, force === true]);
  if (!objectiveMonsterReads.has(key)) {
    const read = withUiTimeout(window.botAPI.listMonstersForArea(areaKey, force === true), 20000, uiText('Quest monsters'));
    objectiveMonsterReads.set(key, read);
    read.finally(() => { if (objectiveMonsterReads.get(key) === read) objectiveMonsterReads.delete(key); }).catch(() => {});
  }
  return objectiveMonsterReads.get(key);
}

function objectiveAreaOptions(type) {
  return type === 'dungeon' ? DUNGEON_MAPS : type === 'event' ? EVENT_MAPS : GATE_MAPS;
}

function replaceObjectiveOptions(select, entries, preferred = '') {
  if (!select) return;
  const options = entries.map(([value, label]) => {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = label;
    return option;
  });
  select.replaceChildren(...options);
  if (preferred && entries.some(([value]) => value === preferred)) select.value = preferred;
}

async function loadObjectiveMonsters(areaKey, select, preferred = '', force = false) {
  if (!select) return;
  const current = objectiveRequest(select);
  delete select.dataset.pending;
  select.replaceChildren(new Option(areaKey ? uiText('Loading…') : uiText('Choose an area'), ''));
  if (!areaKey) return;
  select.dataset.pending = 'true';
  try {
    const result = await readObjectiveMonsters(areaKey, force);
    if (!current()) return;
    if (!result?.success) throw new Error(result?.error || uiText('Monster discovery failed'));
    const entries = (result.monsters || []).map(monster => [monster.key, monster.name]);
    replaceObjectiveOptions(select, entries, preferred);
    if (entries.length === 0) select.replaceChildren(new Option(uiText('No monsters found'), ''));
  } catch (error) {
    if (!current()) return;
    select.replaceChildren(new Option(uiText('Could not load monsters'), ''));
    appendLog('ERROR', `${areaKey}: ${error.message}`);
  } finally {
    if (!current()) return;
    if (preferred) {
      if (![...select.options].some(option => option.value === preferred)) select.add(new Option(preferred + uiText(' (saved)'), preferred));
      select.value = preferred;
    }
    delete select.dataset.pending;
  }
}

function renderBattlePassCounters(state) {
  if (!battlePassCounters) return;
  const objectives = state?.page?.objectives || [];
  battlePassCounters.replaceChildren(...objectives.map(objective => {
    const card = document.createElement('div'); card.className = 'objective-counter-card';
    const label = document.createElement('span'); label.textContent = objective.name || objective.type;
    const value = document.createElement('strong');
    value.textContent = `${formatNumber(objective.current)} / ${formatNumber(objective.required)}`;
    card.classList.toggle('is-complete', objective.completed === true);
    card.append(label, value);
    return card;
  }));
}

async function refreshBattlePass() {
  if (!activeAccount) return;
  setRefreshBusy(btnRefreshBattlePass, true);
  setWorkspaceStatus(battlePassStatus, uiText('Reading Battle Pass…'));
  try {
    const result = await window.botAPI.getBattlePass();
    if (!result?.success) throw new Error(result?.error || uiText('Battle Pass could not be read'));
    latestBattlePassState = result.state;
    renderBattlePassCounters(result.state);
    const page = result.state?.page || {};
    const levelText = Number.isFinite(Number(page.level)) ? ` · level ${Number(page.level).toLocaleString()}` : '';
    setWorkspaceStatus(battlePassStatus, page.completed === true
      ? uiText("Battle Pass complete{0}. Automation will not run it.", levelText)
      : page.active
        ? uiText("Daily objectives refreshed{0}.", levelText)
        : uiText('No active Battle Pass was recognized.'), page.active || page.completed ? 'success' : '');
  } catch (error) {
    setWorkspaceStatus(battlePassStatus, error.message, 'error');
  } finally {
    setRefreshBusy(btnRefreshBattlePass, false);
    refreshLucideIcons();
  }
}

async function loadBattlePassPolicy() {
  if (chkBattlePassEnabled) chkBattlePassEnabled.checked = battlePassConfig.enabled === true;
  if (chkBattlePassLootIfAchievable) chkBattlePassLootIfAchievable.checked = battlePassConfig.lootIfAchievable === true;
  if (chkBattlePassSafeCheck) chkBattlePassSafeCheck.checked = battlePassConfig.safeCheck === true;
  replaceObjectiveOptions(selectBattlePassArea, GATE_MAPS, battlePassConfig.areaKey || 'grakthar_3');
  await renderBattlePassTargets(selectBattlePassArea?.value);
}

function switchBattlePassSubview(name) {
  const targets = name === 'targets';
  subtabBattlePassGeneralBtn?.classList.toggle('active', !targets);
  subtabBattlePassTargetsBtn?.classList.toggle('active', targets);
  if (subviewBattlePassGeneral) subviewBattlePassGeneral.style.display = targets ? 'none' : 'flex';
  if (subviewBattlePassTargets) subviewBattlePassTargets.style.display = targets ? 'flex' : 'none';
  if (targets) renderBattlePassTargets(selectBattlePassArea?.value);
}

async function renderBattlePassTargets(areaKey, force = false) {
  if (!battlePassTargetsContent) return;
  battlePassTargetsContent.innerHTML = ("<div class=\"empty-state\">" + uiText("Loading Battle Pass targets…") + "</div>");
  if (!areaKey) return;
  try {
    const result = await window.botAPI.listMonstersForArea(areaKey);
    if (!result?.success) throw new Error(result?.error || uiText('Monster discovery failed'));
    const configured = battlePassConfig.targets?.[areaKey] || {};
    const monsters = result.monsters || [];
    if (monsters.length === 0) {
      battlePassTargetsContent.innerHTML = ("<div class=\"empty-state\">" + uiText("No monsters were found in this Target Gate.") + "</div>");
      return;
    }
    const header = document.createElement('div');
    header.className = 'objective-target-row objective-target-header';
    for (const label of [uiText('Monster'), uiText('Damage'), uiText('Priority'), uiText('Target')]) {
      const cell = document.createElement('span'); cell.textContent = label; header.append(cell);
    }
    const rows = monsters.map(monster => {
      const policy = configured[monster.key] || {};
      const row = document.createElement('div'); row.className = 'objective-target-row';
      row.dataset.monsterKey = monster.key;
      row.dataset.monsterName = monster.name;
      const name = document.createElement('strong'); name.textContent = monster.name;
      const damage = document.createElement('input'); damage.type = 'number'; damage.min = '300000'; damage.className = 'tree-input-sm'; damage.dataset.field = 'targetDamage'; damage.value = Math.max(300000, Number(policy.targetDamage) || 300000);
      const priority = document.createElement('input'); priority.type = 'number'; priority.min = '0'; priority.className = 'tree-input-sm'; priority.dataset.field = 'priority'; priority.value = Math.max(0, Number(policy.priority) || 0);
      const enabled = document.createElement('input'); enabled.type = 'checkbox'; enabled.className = 'tree-checkbox'; enabled.dataset.field = 'enabled'; enabled.checked = policy.enabled === true;
      row.append(name, damage, priority, enabled);
      return row;
    });
    battlePassTargetsContent.replaceChildren(header, ...rows);
    enhanceNumberInputs(battlePassTargetsContent);
  } catch (error) {
    battlePassTargetsContent.innerHTML = `<div class="empty-state">${escapeHtml(error.message)}</div>`;
  }
}

async function saveBattlePassPatch(patch, button) {
  if (button) button.disabled = true;
  try {
    const result = await updateCanonicalConfig({ battlePass: patch });
    if (!result?.success) throw new Error(result?.error || uiText('Battle Pass settings could not be saved'));
    battlePassConfig = result.config?.battlePass || { ...battlePassConfig, ...patch };
    setWorkspaceStatus(battlePassStatus, uiText('Battle Pass settings saved.'), 'success');
    return true;
  } catch (error) {
    setWorkspaceStatus(battlePassStatus, error.message, 'error');
    return false;
  } finally {
    if (button) button.disabled = false;
  }
}

